      'typography',
      ['font', 'monospace', 'nerd font', 'glyphs', 'shell'],
      'terminalFont'
    ),
    interfaceMode: {
      subpage: 'window-layout',
      keywords: ['simple', 'advanced', 'mode', 'interface', 'chrome', 'minimal', 'focus'],
      copy: t => ({ label: t.interfaceMode.title, description: t.interfaceMode.hint })
