    backdrop: appearanceSetting('window-layout', ['background', 'blur'], 'backdrop'),
    fileBrowser: appearanceSetting(
      'window-layout',
      ['file browser', 'files', 'file tree', 'explorer', 'right sidebar', 'panel', 'startup'],
      'fileBrowser'
