      subpage: 'desktop',
      keywords: ['quick entry', 'global shortcut', 'spotlight', 'summon', 'prompt anywhere'],
      available: canUseQuickEntry,
      copy: t => ({ label: t.settings.quickEntry.enabledTitle, description: t.settings.quickEntry.enabledDesc })
    },
