      subpage: 'desktop',
      keywords: ['quick entry', 'shortcut', 'hotkey', 'keybind', 'chord'],
      available: canUseQuickEntry,
      copy: t => ({ label: t.settings.quickEntry.shortcutTitle, description: t.settings.quickEntry.shortcutDesc })
    }
