    connectionMode: {
      subpage: 'connection',
      keywords: ['gateway', 'connection', 'local', 'cloud', 'remote', 'ssh', 'url', 'token', 'host', 'port', 'key'],
      copy: t => ({ label: t.settings.gateway.modeTitle, description: t.settings.gateway.intro })
    },
