      subpage: 'connection',
      keywords: ['keychain', 'encrypt', 'secrets', 'secure storage', 'plain text'],
      copy: t => ({
        label: t.settings.gateway.keychainEncryptionTitle,
        description: t.settings.gateway.keychainEncryptionDesc
      })
    },
