      subpage: 'connection',
      keywords: ['diagnostics', 'logs', 'debug', 'report', 'troubleshoot'],
      copy: t => ({ label: t.settings.gateway.diagnostics, description: t.settings.gateway.diagnosticsDesc })
    }
