  about: {
    updates: {
      subpage: 'updates',
      keywords: ['update', 'auto update', 'download', 'release', 'version'],
      copy: t => ({ label: t.settings.about.updates })
    }
  }
} as const satisfies Record<string, Record<string, SettingDefinition>>

Object.fromEntries(
